Voici une idée de la façon de coder le jeu du serpent en C, en utilisant des images pour animer tout le niveau :

1. Créez un projet C en utilisant un environnement de développement intégré (IDE) comme Visual Studio ou Code::Blocks.

2. Téléchargez et ajoutez les images de serpent, pomme et mur dans votre projet. Vous pouvez trouver des images gratuites sur des sites comme OpenGameArt ou Freepik.

3. Créez un header (`.h`) pour définir les structures, constantes et prototypes de fonction utilisés dans votre programme :

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <SDL2/SDL.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define SNAKE_SIZE 20
#define APPLE_SIZE 20
#define WALL_SIZE 20

// Structure du serpent
typedef struct {
    int x, y;
} SnakePart;

// Structure de la pomme
typedef struct {
    int x, y;
} Apple;

// Structure du mur
typedef struct {
    int x, y;
} Wall;

// Structure du jeu
typedef struct {
    SDL_Window *window;
    SDL_Renderer *renderer;
    SnakePart *snake;
    int snakeLength;
    Apple apple;
    Wall walls[4];
    int score;
    int direction;
    int gameover;
} Game;

// Prototypes des fonctions
void initGame(Game *game);
void renderGame(Game *game);
void updateGame(Game *game);
void handleInput(Game *game);
void placeApple(Game *game);
void placeWalls(Game *game);
int isGameOver(Game *game);
void gameOver(Game *game);
void cleanUpGame(Game *game);
```

4. Créez un fichier source (`.c`) pour implémenter les fonctions :

```c
#include "game.h"

// Initialisation du jeu
void initGame(Game *game) {
    // Initialisation de la SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Erreur d'initialisation de la SDL : %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }

    // Création de la fenêtre et du rendu
    game->window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH,
        WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    if (game->window == NULL) {
        printf("Erreur de création de la fenêtre : %s\n", SDL_GetError());
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    game->renderer = SDL_CreateRenderer(
        game->window,
        -1,
        SDL_RENDERER_ACCELERATED
    );

    if (game->renderer == NULL) {
        printf("Erreur de création du rendu : %s\n", SDL_GetError());
        SDL_DestroyWindow(game->window);
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    // Initialisation du serpent
    game->snake = (SnakePart*)malloc(sizeof(SnakePart) * 3);
    game->snakeLength = 3;
    game->snake[0].x = WINDOW_WIDTH / 2;
    game->snake[0].y = WINDOW_HEIGHT / 2;
    game->snake[1].x = game->snake[0].x - SNAKE_SIZE;
    game->snake[1].y = game->snake[0].y;
    game->snake[2].x = game->snake[1].x - SNAKE_SIZE;
    game->snake[2].y = game->snake[1].y;

    // Initialisation de la pomme
    placeApple(game);

    // Initialisation du mur
    placeWalls(game);

    // Initialisation des autres variables
    game->score = 0;
    game->direction = SDL_SCANCODE_LEFT;
    game->gameover = 0;
}

// Affichage du jeu
void renderGame(Game *game) {
    SDL_SetRenderDrawColor(game->renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(game->renderer);

    // Affichage du serpent
    for (int I = 0; I < game->snakeLength; i++) {
        SDL_Rect snakeRect = {
            game->snake[i].x,
            game->snake[i].y,
            SNAKE_SIZE,
            SNAKE_SIZE
        };
        SDL_SetTextureColorMod(game->renderer, 0, 255, 0);
        SDL_RenderCopy(game->renderer, SDL_LoadBMP("snake.bmp"), NULL, &snakeRect);
    }

    // Affichage de la pomme
    SDL_Rect appleRect = {
        game->apple.x,
        game->apple.y,
        APPLE_SIZE,
        APPLE_SIZE
    };
    SDL_SetTextureColorMod(game->renderer, 255, 0, 0);
    SDL_RenderCopy(game->renderer, SDL_LoadBMP("apple.bmp"), NULL, &appleRect);

    // Affichage du mur
    for (int I = 0; I < 4; i++) {
        SDL_Rect wallRect = {
            game->walls[i].x,
            game->walls[i].y,
            WALL_SIZE,
            WALL_SIZE
        };
        SDL_SetTextureColorMod(game->renderer, 255, 255, 255);
        SDL_RenderCopy(game->renderer, SDL_LoadBMP("wall.bmp"), NULL, &wallRect);
    }

    // Affichage du score
    char scoreText[10];
    sprintf(scoreText, "Score : %d", game->score);
    SDL_Surface *scoreSurface = TTF_RenderText_Solid(
        SDL_GetTTFFont(),
        scoreText,
        { 255, 255, 255 }
    );
    SDL_Rect scoreRect = {
        10, 10, scoreSurface->w, scoreSurface->h
    };
    SDL_RenderCopy(game->renderer, scoreSurface, NULL, &scoreRect);
    SDL_FreeSurface(scoreSurface);

    // Affichage du message de fin de partie
    if (game->gameover) {
        char gameOverText[20];
        sprintf(gameOverText, "Game Over !");
        SDL_Surface *gameOverSurface = TTF_RenderText_Solid(
            SDL_GetTTFFont(),
            gameOverText,
            { 255, 0, 0 }
        );
        SDL_Rect gameOverRect = {
            (WINDOW_WIDTH - gameOverSurface->w) / 2,
            (WINDOW_HEIGHT - gameOverSurface->h) / 2,
            gameOverSurface->w, gameOverSurface->h
        };
        SDL_RenderCopy(game->renderer, gameOverSurface, NULL, &gameOverRect);
        SDL_FreeSurface(gameOverSurface);
    }

    // Rafraichissement de l'écran
    SDL_RenderPresent(game->renderer);
}

// Mise à jour du jeu
void updateGame(Game *game) {
    // Mise à jour de la position du serpent
    for (int I = game->snakeLength - 1; I > 0; i--) {
        game->snake[i].x = game->snake[i - 1].x;
        game->snake[i].y = game->snake[i - 1].y;
    }

    switch (game->direction) {
        case SDL_SCANCODE_LEFT:
            game->snake[0].x -= SNAKE_SIZE;
            break;
        case SDL_SCANCODE_RIGHT:
            game->snake[0].x += SNAKE_SIZE;
            break;
        case SDL_SCANCODE_UP:
            game->snake[0].y -= SNAKE_SIZE;
            break;
        case SDL_SCANCODE_DOWN:
            game->snake[0].y += SNAKE_SIZE;
            break;
    }

    // Collision avec la pomme
    if (
        game->snake[0].x >= game->apple.x && game->snake[0].x < (game->apple.x + APPLE_SIZE)
        && game->snake[0].y >= game->apple.y && game->snake[0].y < (game->apple.y + APPLE_SIZE)
    ) {
        game->score++;
        game->snakeLength++;
        placeApple(game);
    }

    // Collision avec le mur
    for (int I = 0; I < 4; i++) {
        if (
            game->snake[0].x >= game->walls[i].x && game->snake[0].x < (game->walls[i].x + WALL_SIZE)
            && game->snake[0].y >= game->walls[i].y && game->snake[0].y < (game->walls[i].y + WALL_SIZE)
        ) {
            game->gameover = 1;
            break;
        }
    }

    // Collision avec le serpent
    for (int I = 1; I < game->snakeLength; i++) {
        if (
            game->snake[0].x == game->snake[i].x && game->snake[0].y == game->snake[i].y
        ) {
            game->gameover = 1;
            break;
        }
    }
}

// Gestion des entrées utilisateur
void handleInput(Game *game) {
    SDL_Event event;
    while (SDL_PollEvent(&event)) {
        switch (event.type) {
            case SDL_QUIT:
                game->gameover = 1;
                break;
